import math

def rotate_pair(x1: float, x2: float, angle: float) -> tuple:
    """Standard 2D rotation of (x1, x2) by angle radians."""
    c, s = math.cos(angle), math.sin(angle)
    return round(x1 * c - x2 * s, 6), round(x1 * s + x2 * c, 6)

print(rotate_pair(1.0, 0.0, 0.5))

import math

def rotate_pair(x1: float, x2: float, angle: float) -> tuple:
    c, s = math.cos(angle), math.sin(angle)
    return round(x1*c - x2*s, 6), round(x1*s + x2*c, 6)

def rope_dot_product(q1: float, q2: float, k1: float, k2: float, pos_q: int, pos_k: int, theta: float) -> float:
    """Dot product of the RoPE-rotated query and key pairs."""
    rq1, rq2 = rotate_pair(q1, q2, pos_q * theta)
    rk1, rk2 = rotate_pair(k1, k2, pos_k * theta)
    return round(rq1*rk1 + rq2*rk2, 4)

print(rope_dot_product(1.0, 0.0, 0.6, 0.8, 3, 1, 0.5))
print(rope_dot_product(1.0, 0.0, 0.6, 0.8, 7, 5, 0.5))
print(rope_dot_product(1.0, 0.0, 0.6, 0.8, 10, 8, 0.5))
